/*
 * lib/nn against the golden vectors in lib/nn/tests/vectors/ (generated by
 * python/tests/test_nn.py from the pure-Python reference): every op within
 * 1e-5 relative / 1e-6 absolute, LSTM state kept and reset, unknown ops
 * refused, each load check failing in turn on a mutated file, BLAKE2s and
 * FNV vectors, the pinned layout, and a 2-layer LSTM stepped 1000 times
 * with its timing printed. Runs from the repository root, or with
 * HANGAR_NN_VECTORS pointing at the vectors directory.
 */
#define _POSIX_C_SOURCE 200809L
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#include "blake2s.h"
#include "nn_graph.h"
#include "nn_hgw.h"
#include "nn_ops.h"
#include "test_harness.h"

#ifndef NN_VECTORS_DIR
#define NN_VECTORS_DIR "lib/nn/tests/vectors"
#endif

#define REL_TOL 1e-5f
#define ABS_TOL 1e-6f

static const char *vectors_dir(void) {
  const char *e = getenv("HANGAR_NN_VECTORS");
  return e && *e ? e : NN_VECTORS_DIR;
}

/* The golden file read into a 64-byte aligned, writable buffer (the tests
 * mutate copies), and its sidecar. */
typedef struct golden {
  uint8_t *data;
  size_t size;
  uint8_t blake2s[32];
  uint64_t arch;
  unsigned steps;
  unsigned n_state;
  double state[512];
} golden;

static int hexval(char c) {
  if (c >= '0' && c <= '9')
    return c - '0';
  if (c >= 'a' && c <= 'f')
    return c - 'a' + 10;
  if (c >= 'A' && c <= 'F')
    return c - 'A' + 10;
  return -1;
}

static bool load_golden(const char *name, golden *g) {
  char path[512];
  FILE *f;
  long n;
  char line[16384];
  memset(g, 0, sizeof *g);
  snprintf(path, sizeof path, "%s/%s.hgw", vectors_dir(), name);
  f = fopen(path, "rb");
  if (!f) {
    printf("    cannot open %s\n", path);
    return false;
  }
  fseek(f, 0, SEEK_END);
  n = ftell(f);
  fseek(f, 0, SEEK_SET);
  g->size = (size_t)n;
  g->data = aligned_alloc(64, (g->size + 63) / 64 * 64);
  if (fread(g->data, 1, g->size, f) != g->size) {
    fclose(f);
    return false;
  }
  fclose(f);
  snprintf(path, sizeof path, "%s/%s.golden.txt", vectors_dir(), name);
  f = fopen(path, "r");
  if (!f) {
    printf("    cannot open %s\n", path);
    return false;
  }
  while (fgets(line, sizeof line, f)) {
    if (strncmp(line, "blake2s ", 8) == 0) {
      int i;
      for (i = 0; i < 32; i++)
        g->blake2s[i] = (uint8_t)(hexval(line[8 + 2 * i]) * 16 + hexval(line[9 + 2 * i]));
    } else if (strncmp(line, "arch ", 5) == 0) {
      g->arch = strtoull(line + 5, NULL, 16);
    } else if (strncmp(line, "steps ", 6) == 0) {
      g->steps = (unsigned)strtoul(line + 6, NULL, 10);
    } else if (strncmp(line, "state ", 6) == 0) {
      char *p = line + 6, *end;
      unsigned i;
      g->n_state = (unsigned)strtoul(p, &end, 10);
      p = end;
      for (i = 0; i < g->n_state && i < 512; i++) {
        g->state[i] = strtod(p, &end);
        p = end;
      }
    }
  }
  fclose(f);
  return true;
}

static void free_golden(golden *g) {
  free(g->data);
  g->data = NULL;
}

static golden *copy_golden(const golden *g, golden *out) {
  *out = *g;
  out->data = aligned_alloc(64, (g->size + 63) / 64 * 64);
  memcpy(out->data, g->data, g->size);
  return out;
}

/* After a mutation of the graph: recompute the header's arch hash so that
 * check 2 passes and the later check under test is reached. */
static uint64_t resign(golden *g) {
  nn_hgw_file f;
  char why[128];
  nn_hgw_header *h = (nn_hgw_header *)g->data;
  if (nn_hgw_parse(g->data, g->size, &f, why, sizeof why) < 0) {
    printf("    resign: parse failed: %s\n", why);
    return 0;
  }
  h->arch_hash = nn_hgw_arch_hash(&f);
  return h->arch_hash;
}

static bool close_enough(float got, double want) {
  return fabs((double)got - want) <= ABS_TOL + REL_TOL * fabs(want);
}

static nn_load_req req_for(const golden *g) {
  nn_load_req r;
  memset(&r, 0, sizeof r);
  r.file_hash = g->blake2s;
  r.arch = g->arch;
  return r;
}

/* Steps the model through probe `p` with nn_step and compares every output
 * with the probe's expected values within the test tolerance. Returns the
 * number of mismatches. */
static int run_probe_compare(nn_model *m, unsigned p, const char *tag) {
  const nn_hgw_file *f = &m->file;
  const nn_hgw_probe *pr = &f->probes[p];
  size_t stride = nn_probe_stride(m);
  const void *in[64];
  float *out[64];
  float outbuf[64][64];
  unsigned s, i, j;
  int bad = 0;
  for (j = 0; j < m->n_outputs; j++)
    out[j] = outbuf[j];
  for (s = 0; s < pr->steps; s++) {
    const uint8_t *rec = f->data + pr->offset + (size_t)s * stride;
    size_t off = 0;
    for (i = 0; i < m->n_inputs; i++) {
      in[i] = rec + off;
      off += (nn_input_bytes(m, i) + 7) / 8 * 8;
    }
    CHECK_EQ_INT(nn_step(m, in, out), NN_OK);
    for (j = 0; j < m->n_outputs; j++) {
      size_t n = nn_output_count(m, j), e;
      const float *want = (const float *)(rec + off);
      for (e = 0; e < n; e++)
        if (!close_enough(out[j][e], (double)want[e])) {
          if (bad < 5)
            printf("    %s: step %u output %u[%zu]: got %.9g, want %.9g\n", tag, s, j, e,
                   (double)out[j][e], (double)want[e]);
          bad++;
        }
      off += (n * 4 + 7) / 8 * 8;
    }
  }
  return bad;
}

/* ---- layout and primitives --------------------------------------------- */

static void test_layout(void) {
  /* The _Static_asserts in nn_hgw.h are the test; this checks the runtime
   * view of a golden file agrees with them. */
  golden g;
  nn_hgw_file f;
  char why[128];
  if (!load_golden("depth_ff", &g)) {
    CHECK(false);
    return;
  }
  CHECK_EQ_INT(sizeof(nn_hgw_header), 4096);
  CHECK_EQ_INT(sizeof(nn_hgw_op), 192);
  CHECK_EQ_INT(sizeof(nn_hgw_tensor), 80);
  CHECK_EQ_INT(sizeof(nn_hgw_buffer), 64);
  CHECK_EQ_INT(sizeof(nn_hgw_binding), 64);
  CHECK_EQ_INT(sizeof(nn_hgw_probe), 32);
  CHECK_EQ_INT(nn_hgw_parse(g.data, g.size, &f, why, sizeof why), 0);
  CHECK(memcmp(f.hdr->magic, "HGWEIGHT", 8) == 0);
  CHECK_EQ_INT(f.hdr->format_version, 1);
  CHECK_EQ_INT(f.hdr->section_dir_offset, 4096);
  CHECK_EQ_INT(f.hdr->tensor_data_offset % 64, 0);
  CHECK_EQ_INT(f.n_ops, 5);
  CHECK_EQ_INT(f.n_tensors, 12);
  CHECK_EQ_INT(f.n_buffers, 6);
  CHECK_EQ_INT(f.n_inputs, 5);
  CHECK_EQ_INT(f.n_outputs, 1);
  CHECK_EQ_INT(f.n_probes, 2);
  CHECK_EQ_INT(f.n_ranges, 5);
  CHECK(strcmp(f.hdr->name, "depth_ff") == 0);
  CHECK(strcmp(f.hdr->dataset, "depth_ff") == 0);
  CHECK_EQ_INT(f.hdr->tick_period_ns, 20000000);
  CHECK_EQ_INT(f.hdr->warmup_ticks, 50);
  CHECK_EQ_INT(f.hdr->lineage_count, 1);
  CHECK(strcmp(f.hdr->sessions[0].session, "20261107T120000") == 0);
  CHECK_EQ_INT(f.hdr->ranges[0].rows, 12345);
  CHECK(f.hdr->dataset_hash == 0xD0D0CAFEF00D0001ull);
  CHECK(f.hdr->arch_hash == g.arch);
  CHECK(nn_hgw_arch_hash(&f) == g.arch);
  CHECK(strcmp(f.ops[2].type, "lstm") == 0);
  CHECK(f.ops[2].attrs[1] == 16.0);
  CHECK(strcmp(f.inputs[4].field, "ctl.depth_hold.target.accel_z") == 0);
  CHECK(strcmp(f.outputs[0].field, "heave") == 0);
  free_golden(&g);
}

static void canon_sink(void *ctx, const char *bytes, size_t n) {
  char *buf = (char *)ctx;
  size_t len = strlen(buf);
  if (len + n < 4096) {
    memcpy(buf + len, bytes, n);
    buf[len + n] = 0;
  }
}

static void test_arch_canon(void) {
  golden g;
  nn_hgw_file f;
  char canon[4096] = {0};
  const char *expect =
      "hgw-arch-1\n"
      "buffers 3\n"
      "buffer 0 1 1 5\n"
      "buffer 1 1 1 4\n"
      "buffer 2 1 1 4\n"
      "tensors 2\n"
      "tensor 0 1 2 4 5\n"
      "tensor 1 1 1 4\n"
      "ops 2\n"
      "op 0 dense 1 attrs 3 4014000000000000 4010000000000000 3ff0000000000000 in 1 0 out 1 tensors 2 0 1\n"
      "op 1 relu 1 attrs 0 in 1 1 out 2 tensors 0\n"
      "inputs 5\n"
      "input 0 0 nav.state.depth\n"
      "input 0 1 nav.state.vel_z\n"
      "input 0 2 nav.state.pitch\n"
      "input 0 3 nav.state.roll\n"
      "input 0 4 nav.state.accel_z\n"
      "outputs 4\n"
      "output 2 0 wrench.surge\n"
      "output 2 1 wrench.sway\n"
      "output 2 2 wrench.heave\n"
      "output 2 3 wrench.yaw\n";
  if (!load_golden("dense_relu", &g)) {
    CHECK(false);
    return;
  }
  CHECK_EQ_INT(nn_hgw_parse(g.data, g.size, &f, NULL, 0), 0);
  nn_hgw_arch_canon(&f, canon_sink, canon);
  if (strcmp(canon, expect) != 0)
    printf("    canonical text:\n%s", canon);
  CHECK(strcmp(canon, expect) == 0);
  CHECK(nn_fnv1a64(NN_FNV1A64_OFFSET, expect, strlen(expect)) == g.arch);
  CHECK(nn_hgw_arch_hash(&f) == g.arch);
  free_golden(&g);
}

static void test_fnv1a64(void) {
  CHECK(nn_fnv1a64(NN_FNV1A64_OFFSET, "", 0) == 0xcbf29ce484222325ull);
  CHECK(nn_fnv1a64(NN_FNV1A64_OFFSET, "a", 1) == 0xaf63dc4c8601ec8cull);
  CHECK(nn_fnv1a64(NN_FNV1A64_OFFSET, "foobar", 6) == 0x85944171f73967e8ull);
}

static void hex_to_bytes(const char *hex, uint8_t *out, size_t n) {
  size_t i;
  for (i = 0; i < n; i++)
    out[i] = (uint8_t)(hexval(hex[2 * i]) * 16 + hexval(hex[2 * i + 1]));
}

static void check_blake2s(const void *in, size_t n, const void *key, size_t keylen,
                          size_t outlen, const char *hex) {
  uint8_t want[32], got[32];
  hex_to_bytes(hex, want, outlen);
  CHECK_EQ_INT(nn_blake2s(got, outlen, in, n, key, keylen), 0);
  CHECK_MEM_EQ(got, want, outlen);
}

static void test_blake2s(void) {
  uint8_t seq[256];
  int i;
  nn_blake2s_state s;
  uint8_t got[32], want[32];
  for (i = 0; i < 256; i++)
    seq[i] = (uint8_t)i;
  /* RFC 7693 appendix B */
  check_blake2s("abc", 3, NULL, 0, 32,
                "508c5e8c327c14e2e1a72ba34eeb452f37458b209ed63a294d999b4c86675982");
  /* the rest from Python's hashlib.blake2s */
  check_blake2s("", 0, NULL, 0, 32,
                "69217a3079908094e11121d042354a7c1f55b6482ca1a51e1b250dfd1ed0eef9");
  check_blake2s(seq, 256, NULL, 0, 32,
                "5fdeb59f681d975f52c8e69c5502e02a12a3afcc5836ba58f42784c439228781");
  check_blake2s(seq, 64, NULL, 0, 32, /* exactly one block */
                "56f34e8b96557e90c1f24b52d0c89d51086acf1b00f634cf1dde9233b8eaaa3e");
  check_blake2s(seq, 65, NULL, 0, 32, /* one block and a byte */
                "1b53ee94aaf34e4b159d48de352c7f0661d0a40edff95a0b1639b4090e974472");
  check_blake2s(seq, 7, seq, 32, 32, /* keyed */
                "e6c8125637438d0905b749f46560ac89fd471cf8692e28fab982f73f019b83a9");
  check_blake2s("abc", 3, NULL, 0, 16, "aa4938119b1dc7b87cbad0ffd200d0ae");
  /* incremental == one shot, across odd boundaries */
  nn_blake2s_init(&s, 32);
  for (i = 0; i < 256; i += 13)
    nn_blake2s_update(&s, seq + i, (size_t)(i + 13 <= 256 ? 13 : 256 - i));
  nn_blake2s_final(&s, got, 32);
  hex_to_bytes("5fdeb59f681d975f52c8e69c5502e02a12a3afcc5836ba58f42784c439228781", want, 32);
  CHECK_MEM_EQ(got, want, 32);
  CHECK_EQ_INT(nn_blake2s(got, 0, "", 0, NULL, 0), -1);
  CHECK_EQ_INT(nn_blake2s(got, 33, "", 0, NULL, 0), -1);
}

/* ---- the golden models ------------------------------------------------- */

/* Loads a golden file (checks 1 to 6 with the file's own tolerance), then
 * steps probe 0 under the test tolerance with every available kernel of
 * every op, and checks LSTM state against the sidecar. */
static void golden_case(const char *name) {
  golden g;
  nn_model *m = NULL;
  nn_report rep;
  nn_load_req req;
  unsigned i;
  if (!load_golden(name, &g)) {
    CHECK(false);
    return;
  }
  req = req_for(&g);
  if (nn_load_mem(g.data, g.size, &req, &m, &rep) < 0) {
    printf("    %s: load failed at check %d (%s): %s\n", name, rep.check, rep.name, rep.reason);
    CHECK(false);
    free_golden(&g);
    return;
  }
  CHECK_EQ_INT(rep.check, 0);
  CHECK(rep.arch_hash == g.arch);
  CHECK(rep.probe_steps >= g.steps);
  CHECK(rep.step_ns > 0);
  /* the loader left the state at zero */
  for (i = 0; i < m->n_ops; i++) {
    size_t bytes;
    const float *st = nn_op_state(m, i, &bytes);
    size_t k;
    for (k = 0; st && k < bytes / 4; k++)
      CHECK(st[k] == 0.0f);
  }
  CHECK_EQ_INT(run_probe_compare(m, 0, name), 0);
  /* the recurrent state after the probe, against the reference's doubles */
  {
    unsigned idx = 0;
    for (i = 0; i < m->n_ops; i++) {
      size_t bytes, k;
      const float *st = nn_op_state(m, i, &bytes);
      for (k = 0; st && k < bytes / 4; k++, idx++)
        if (idx < g.n_state && !close_enough(st[k], g.state[idx])) {
          printf("    %s: state[%u] got %.9g want %.9g\n", name, idx, (double)st[k], g.state[idx]);
          CHECK(false);
        }
    }
    CHECK_EQ_INT(idx, g.n_state);
  }
  /* reset: zero state, and step 0 reproduces */
  nn_reset(m);
  for (i = 0; i < m->n_ops; i++) {
    size_t bytes, k;
    const float *st = nn_op_state(m, i, &bytes);
    for (k = 0; st && k < bytes / 4; k++)
      CHECK(st[k] == 0.0f);
  }
  CHECK_EQ_INT(run_probe_compare(m, 0, name), 0);
  /* every kernel of every op reproduces the vectors */
  for (i = 0; i < m->n_ops; i++) {
    const nn_op_def *def = m->ops[i].def;
    size_t k;
    for (k = 0; k < def->n_kernels; k++) {
      if (!def->kernels[k].available())
        continue;
      m->ops[i].kernel = &def->kernels[k];
      nn_reset(m);
      CHECK_EQ_INT(run_probe_compare(m, 0, def->kernels[k].name), 0);
    }
    m->ops[i].kernel = nn_op_select_kernel(def);
  }
  nn_free(m);
  free_golden(&g);
}

static void test_dense_relu(void) { golden_case("dense_relu"); }
static void test_lstm1(void) { golden_case("lstm1"); }
static void test_lstm2(void) { golden_case("lstm2"); }
static void test_affine_cast(void) { golden_case("affine_cast"); }
static void test_casts(void) { golden_case("casts"); }
static void test_acts(void) { golden_case("acts"); }
static void test_depth_ff(void) { golden_case("depth_ff"); }

/* The LSTM's memory: stepping the same input twice gives two different
 * outputs; after a reset the first comes back; stepping without a reset
 * continues from the kept state. */
static void test_lstm_state_kept(void) {
  golden g;
  nn_model *m = NULL;
  nn_report rep;
  nn_load_req req;
  float x[3] = {0.5f, -0.25f, 1.0f};
  float y1[4], y2[4], y3[4], y4[4];
  const void *in[1] = {x};
  float *out[1];
  size_t bytes;
  const float *st;
  if (!load_golden("lstm1", &g)) {
    CHECK(false);
    return;
  }
  req = req_for(&g);
  CHECK_EQ_INT(nn_load_mem(g.data, g.size, &req, &m, &rep), 0);
  if (!m) {
    free_golden(&g);
    return;
  }
  out[0] = y1;
  CHECK_EQ_INT(nn_step(m, in, out), NN_OK);
  out[0] = y2;
  CHECK_EQ_INT(nn_step(m, in, out), NN_OK);
  CHECK(memcmp(y1, y2, sizeof y1) != 0);
  st = nn_op_state(m, 0, &bytes);
  CHECK_EQ_INT(bytes, 2 * 4 * sizeof(float));
  CHECK(st[0] != 0.0f);
  CHECK(st[4] != 0.0f); /* c */
  CHECK_EQ_INT(m->steps, 2);
  nn_reset(m);
  CHECK(st[0] == 0.0f && st[7] == 0.0f);
  out[0] = y3;
  CHECK_EQ_INT(nn_step(m, in, out), NN_OK);
  CHECK_MEM_EQ(y3, y1, sizeof y1);
  out[0] = y4;
  CHECK_EQ_INT(nn_step(m, in, out), NN_OK);
  CHECK_MEM_EQ(y4, y2, sizeof y2);
  nn_free(m);
  free_golden(&g);
}

/* A non-finite input: nothing written, state reset, counted. */
static void test_nonfinite(void) {
  golden g;
  nn_model *m = NULL;
  nn_report rep;
  nn_load_req req;
  float x[3] = {0.5f, -0.25f, 1.0f};
  float y[4] = {7, 7, 7, 7};
  const void *in[1] = {x};
  float *out[1] = {y};
  size_t bytes;
  const float *st;
  if (!load_golden("lstm1", &g)) {
    CHECK(false);
    return;
  }
  req = req_for(&g);
  CHECK_EQ_INT(nn_load_mem(g.data, g.size, &req, &m, &rep), 0);
  if (!m) {
    free_golden(&g);
    return;
  }
  CHECK_EQ_INT(nn_step(m, in, out), NN_OK);
  st = nn_op_state(m, 0, &bytes);
  CHECK(st[0] != 0.0f);
  x[1] = NAN;
  y[0] = y[1] = y[2] = y[3] = 7.0f;
  CHECK_EQ_INT(nn_step(m, in, out), NN_ERR_NONFINITE);
  CHECK(y[0] == 7.0f && y[3] == 7.0f);
  CHECK(st[0] == 0.0f && st[7] == 0.0f);
  CHECK_EQ_INT(m->nonfinite_count, 1);
  x[1] = -0.25f;
  CHECK_EQ_INT(nn_step(m, in, out), NN_OK);
  CHECK(y[0] != 7.0f);
  nn_free(m);
  free_golden(&g);
  /* An infinity through an LSTM is squashed to a finite value by its gates;
   * through dense + relu it reaches the output. */
  if (!load_golden("dense_relu", &g)) {
    CHECK(false);
    return;
  }
  req = req_for(&g);
  m = NULL;
  CHECK_EQ_INT(nn_load_mem(g.data, g.size, &req, &m, &rep), 0);
  if (!m) {
    free_golden(&g);
    return;
  }
  {
    float x5[5] = {0.1f, 0.2f, INFINITY, 0.3f, 0.4f};
    const void *in5[1] = {x5};
    y[0] = y[3] = 7.0f;
    CHECK_EQ_INT(nn_step(m, in5, out), NN_ERR_NONFINITE);
    CHECK(y[0] == 7.0f && y[3] == 7.0f);
    CHECK_EQ_INT(m->nonfinite_count, 1);
    x5[2] = 0.0f;
    CHECK_EQ_INT(nn_step(m, in5, out), NN_OK);
  }
  nn_free(m);
  free_golden(&g);
}

/* ---- refusals ---------------------------------------------------------- */

static void expect_refused(golden *g, const nn_load_req *req, int check, const char *needle,
                           const char *what) {
  nn_model *m = (nn_model *)1;
  nn_report rep;
  int rc = nn_load_mem(g->data, g->size, req, &m, &rep);
  CHECK_EQ_INT(rc, -1);
  CHECK(m == NULL);
  if (rep.check != check || (needle && !strstr(rep.reason, needle)))
    printf("    %s: check %d (%s): %s\n", what, rep.check, rep.name, rep.reason);
  CHECK_EQ_INT(rep.check, check);
  if (needle)
    CHECK(strstr(rep.reason, needle) != NULL);
}

static void test_unknown_op_refused(void) {
  golden g, c;
  nn_load_req req;
  nn_hgw_file f;
  nn_hgw_op *op;
  if (!load_golden("dense_relu", &g)) {
    CHECK(false);
    return;
  }
  /* conv2d v1 in place of dense */
  copy_golden(&g, &c);
  nn_hgw_parse(c.data, c.size, &f, NULL, 0);
  op = (nn_hgw_op *)&f.ops[0];
  memset(op->type, 0, sizeof op->type);
  strcpy(op->type, "conv2d");
  req = req_for(&c);
  req.file_hash = NULL;
  req.arch = resign(&c);
  expect_refused(&c, &req, 3, "op conv2d v1 not supported", "conv2d");
  free_golden(&c);
  /* dense v2 */
  copy_golden(&g, &c);
  nn_hgw_parse(c.data, c.size, &f, NULL, 0);
  op = (nn_hgw_op *)&f.ops[0];
  op->version = 2;
  req.arch = resign(&c);
  expect_refused(&c, &req, 3, "op dense v2 not supported", "dense v2");
  free_golden(&c);
  /* each of the Later ops by name */
  {
    const char *later[] = {"maxpool2d", "avgpool2d", "global_avgpool", "add", "concat",
                           "flatten", "reshape"};
    size_t i;
    for (i = 0; i < sizeof later / sizeof later[0]; i++) {
      char needle[64];
      copy_golden(&g, &c);
      nn_hgw_parse(c.data, c.size, &f, NULL, 0);
      op = (nn_hgw_op *)&f.ops[1];
      memset(op->type, 0, sizeof op->type);
      strcpy(op->type, later[i]);
      req.arch = resign(&c);
      snprintf(needle, sizeof needle, "op %s v1 not supported", later[i]);
      expect_refused(&c, &req, 3, needle, later[i]);
      free_golden(&c);
    }
  }
  CHECK(nn_op_find("conv2d", 1) == NULL);
  CHECK(nn_op_find("dense", 2) == NULL);
  CHECK(nn_op_find("dense", 1) != NULL);
  CHECK_EQ_INT(nn_op_registry_len, 7);
  free_golden(&g);
}

static void test_load_checks(void) {
  golden g, c;
  nn_load_req req;
  nn_hgw_file f;
  nn_model *m = NULL;
  nn_report rep;
  if (!load_golden("depth_ff", &g)) {
    CHECK(false);
    return;
  }
  /* the pristine file loads with every comparison the caller can ask for */
  {
    const char *in_fields[] = {"nav.state.depth", "nav.state.vel_z", "nav.state.pitch",
                               "nav.state.roll", "ctl.depth_hold.target.accel_z", "extra"};
    const char *out_fields[] = {"surge", "sway", "heave", "roll", "pitch", "yaw"};
    req = req_for(&g);
    req.tick_period_ns = 20000000;
    req.dataset = "depth_ff";
    req.dataset_hash = 0xD0D0CAFEF00D0001ull;
    req.input_fields = in_fields;
    req.n_input_fields = 6;
    req.output_fields = out_fields;
    req.n_output_fields = 6;
    req.step_budget_ns = 10e6; /* 50 % of a 20 ms tick */
    CHECK_EQ_INT(nn_load_mem(g.data, g.size, &req, &m, &rep), 0);
    CHECK(m != NULL);
    CHECK_EQ_INT(rep.check, 0);
    CHECK(strcmp(rep.name, "loaded") == 0);
    nn_free(m);
    m = NULL;

    /* 1: file hash */
    {
      uint8_t wrong[32];
      memcpy(wrong, g.blake2s, 32);
      wrong[5] ^= 1;
      req.file_hash = wrong;
      expect_refused(&g, &req, 1, "BLAKE2s", "file hash");
      req.file_hash = g.blake2s;
    }
    /* 2: format version */
    copy_golden(&g, &c);
    ((nn_hgw_header *)c.data)->format_version = 2;
    req.file_hash = NULL;
    expect_refused(&c, &req, 2, "format version 2", "format version");
    free_golden(&c);
    /* 2: a bad magic, a truncated file, a header that lies about the size */
    copy_golden(&g, &c);
    c.data[0] = 'X';
    expect_refused(&c, &req, 2, "magic", "magic");
    free_golden(&c);
    copy_golden(&g, &c);
    c.size -= 64;
    expect_refused(&c, &req, 2, "bytes", "truncated");
    free_golden(&c);
    /* 2: architecture */
    req.file_hash = g.blake2s;
    req.arch = g.arch ^ 0x10;
    expect_refused(&g, &req, 2, "Arch", "wrong arch");
    req.arch = g.arch;
    copy_golden(&g, &c);
    ((nn_hgw_header *)c.data)->arch_hash ^= 1; /* header disagrees with the graph */
    req.file_hash = NULL;
    expect_refused(&c, &req, 2, "hashes to", "header arch");
    free_golden(&c);
    /* 3: an op whose check fails (dense out=17 against W[16,5]) */
    copy_golden(&g, &c);
    nn_hgw_parse(c.data, c.size, &f, NULL, 0);
    ((nn_hgw_op *)&f.ops[1])->attrs[1] = 17.0;
    req.arch = resign(&c);
    expect_refused(&c, &req, 3, "dense", "op check");
    free_golden(&c);
    /* 3: a buffer read before it is written (op order) */
    copy_golden(&g, &c);
    nn_hgw_parse(c.data, c.size, &f, NULL, 0);
    ((nn_hgw_op *)&f.ops[0])->inputs[0] = 3;
    req.arch = resign(&c);
    expect_refused(&c, &req, 3, "before it is written", "op order");
    free_golden(&c);
    req.arch = g.arch;
    req.file_hash = g.blake2s;
    /* 4: tick period, dataset, dataset hash, fields */
    req.tick_period_ns = 10000000;
    expect_refused(&g, &req, 4, "tick", "tick period");
    req.tick_period_ns = 20000000;
    req.dataset = "other";
    expect_refused(&g, &req, 4, "dataset", "dataset name");
    req.dataset = "depth_ff";
    req.dataset_hash = 1;
    expect_refused(&g, &req, 4, "spec hash", "dataset hash");
    req.dataset_hash = 0xD0D0CAFEF00D0001ull;
    req.n_input_fields = 4; /* accel_z gone */
    expect_refused(&g, &req, 4, "no field ctl.depth_hold.target.accel_z", "input field");
    req.n_input_fields = 6;
    req.n_output_fields = 2; /* heave gone */
    expect_refused(&g, &req, 4, "no field heave", "output field");
    req.n_output_fields = 6;
    /* 4: an input element bound twice / an element unbound */
    copy_golden(&g, &c);
    nn_hgw_parse(c.data, c.size, &f, NULL, 0);
    ((nn_hgw_binding *)&f.inputs[4])->element = 0;
    req.arch = resign(&c);
    req.file_hash = NULL;
    expect_refused(&c, &req, 4, "bound twice", "binding dup");
    free_golden(&c);
    /* 5: a NaN in a tensor */
    copy_golden(&g, &c);
    nn_hgw_parse(c.data, c.size, &f, NULL, 0);
    {
      float nan = NAN;
      memcpy(c.data + f.tensors[2].offset + 4 * 3, &nan, 4);
    }
    req.arch = g.arch;
    expect_refused(&c, &req, 5, "fc1.W", "nan tensor");
    free_golden(&c);
    /* 6: a weight nudged: the probes no longer reproduce */
    copy_golden(&g, &c);
    nn_hgw_parse(c.data, c.size, &f, NULL, 0);
    {
      float v;
      memcpy(&v, c.data + f.tensors[8].offset, 4);
      v += 0.5f;
      memcpy(c.data + f.tensors[8].offset, &v, 4);
    }
    expect_refused(&c, &req, 6, "expected", "probe mismatch");
    free_golden(&c);
    /* 6: the activation bound */
    copy_golden(&g, &c);
    ((nn_hgw_header *)c.data)->activation_bound = 1e-3f;
    expect_refused(&c, &req, 6, "activation bound", "bound");
    free_golden(&c);
    /* 6: the ranges section drives an intermediate over a bound the probes
     * stay under: depth up to 50 m, normalized to 4, through fc1 */
    copy_golden(&g, &c);
    ((nn_hgw_header *)c.data)->activation_bound = 2.0f;
    {
      nn_report r2;
      nn_model *m2 = NULL;
      CHECK_EQ_INT(nn_load_mem(c.data, c.size, &req, &m2, &r2), -1);
      CHECK_EQ_INT(r2.check, 6);
      CHECK(strstr(r2.reason, "activation bound") != NULL);
      CHECK(m2 == NULL);
      if (r2.check != 6)
        printf("    bound 2: check %d: %s\n", r2.check, r2.reason);
    }
    free_golden(&c);
    /* 6: no probes */
    copy_golden(&g, &c);
    nn_hgw_parse(c.data, c.size, &f, NULL, 0);
    {
      uint32_t i;
      for (i = 0; i < f.hdr->section_count; i++)
        if (strcmp(f.dir[i].name, "probes") == 0)
          strcpy(((nn_hgw_section *)&f.dir[i])->name, "xprobes");
    }
    expect_refused(&c, &req, 6, "no probes", "no probes");
    free_golden(&c);
    /* 7: the step budget */
    req.file_hash = g.blake2s;
    req.step_budget_ns = 1e-3;
    expect_refused(&g, &req, 7, "budget", "step budget");
    req.step_budget_ns = 0;
    /* an unknown section is skipped: rename ranges */
    copy_golden(&g, &c);
    nn_hgw_parse(c.data, c.size, &f, NULL, 0);
    {
      uint32_t i;
      for (i = 0; i < f.hdr->section_count; i++)
        if (strcmp(f.dir[i].name, "ranges") == 0)
          strcpy(((nn_hgw_section *)&f.dir[i])->name, "future");
    }
    req.file_hash = NULL;
    CHECK_EQ_INT(nn_load_mem(c.data, c.size, &req, &m, &rep), 0);
    CHECK(m != NULL);
    if (m) {
      CHECK_EQ_INT(m->file.n_ranges, 0);
      nn_free(m);
      m = NULL;
    }
    free_golden(&c);
  }
  free_golden(&g);
}

/* nn_load over a path maps the file, and the model reads it in place. */
static void test_load_path(void) {
  char path[512];
  nn_model *m = NULL;
  nn_report rep;
  nn_load_req req;
  golden g;
  if (!load_golden("depth_ff", &g)) {
    CHECK(false);
    return;
  }
  req = req_for(&g);
  snprintf(path, sizeof path, "%s/depth_ff.hgw", vectors_dir());
  CHECK_EQ_INT(nn_load(path, &req, &m, &rep), 0);
  CHECK(m != NULL);
  if (m) {
    CHECK(m->owns_map);
    CHECK_EQ_INT(m->map_size, g.size);
    CHECK_EQ_INT(run_probe_compare(m, 1, "depth_ff via path"), 0);
    nn_free(m);
  }
  snprintf(path, sizeof path, "%s/does_not_exist.hgw", vectors_dir());
  CHECK_EQ_INT(nn_load(path, &req, &m, &rep), -1);
  CHECK(m == NULL);
  CHECK_EQ_INT(rep.check, 2);
  free_golden(&g);
}

/* ---- timing ------------------------------------------------------------ */

static double now_ns(void) {
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (double)ts.tv_sec * 1e9 + (double)ts.tv_nsec;
}

static void time_model(const char *name, double budget_ns) {
  golden g;
  nn_model *m = NULL;
  nn_report rep;
  nn_load_req req;
  float x[64];
  float y[64];
  const void *in[1] = {x};
  float *out[1] = {y};
  unsigned i;
  double t0, dt;
  if (!load_golden(name, &g)) {
    CHECK(false);
    return;
  }
  req = req_for(&g);
  req.step_budget_ns = budget_ns;
  CHECK_EQ_INT(nn_load_mem(g.data, g.size, &req, &m, &rep), 0);
  if (!m) {
    printf("    %s: %s\n", name, rep.reason);
    free_golden(&g);
    return;
  }
  for (i = 0; i < 64; i++)
    x[i] = 0.01f * (float)i - 0.3f;
  for (i = 0; i < 100; i++) /* warm the caches */
    nn_step(m, in, out);
  t0 = now_ns();
  for (i = 0; i < 1000; i++)
    CHECK_EQ_INT(nn_step(m, in, out), NN_OK);
  dt = now_ns() - t0;
  printf("    %-9s 1000 steps: %.1f us/step (loader measured %.1f us on %llu probe steps; budget %.0f us)\n",
         name, dt / 1000 / 1000, rep.step_ns / 1000, (unsigned long long)rep.probe_steps,
         budget_ns / 1000);
  CHECK(dt / 1000 < budget_ns);
  nn_free(m);
  free_golden(&g);
}

static void test_timing(void) {
  /* 50 % of a 20 ms tick */
  time_model("lstm2", 10e6);
  time_model("depth_ff", 10e6);
}

int main(void) {
  RUN_TEST(test_layout);
  RUN_TEST(test_arch_canon);
  RUN_TEST(test_fnv1a64);
  RUN_TEST(test_blake2s);
  RUN_TEST(test_dense_relu);
  RUN_TEST(test_lstm1);
  RUN_TEST(test_lstm2);
  RUN_TEST(test_affine_cast);
  RUN_TEST(test_casts);
  RUN_TEST(test_acts);
  RUN_TEST(test_depth_ff);
  RUN_TEST(test_lstm_state_kept);
  RUN_TEST(test_nonfinite);
  RUN_TEST(test_unknown_op_refused);
  RUN_TEST(test_load_checks);
  RUN_TEST(test_load_path);
  RUN_TEST(test_timing);
  TEST_MAIN_END();
}
